document.addEventListener('submit',async e=>{if(!['review-form','add-form'].includes(e.target.id))return;e.preventDefault();if(e.target.dataset.saving)return;if(stale){notify('请刷新以读取最新记录');return}try{const f=new FormData(e.target);if(e.submitter?.dataset.reviewSubmit==='reopen')f.set('workflowAction',e.submitter.dataset.reviewSubmit);if(e.target.id==='review-form'){const r=state.rows.find(x=>x.id===e.target.dataset.id);if(!r)throw Error('该线索已更新，请关闭后重新打开');const savedReviewAt=new Date().toISOString(),values=reviewValues(f,r,savedReviewAt),prior=structuredClone(r);e.target.dataset.saving='true';for(const button of e.target.querySelectorAll('[type=submit]')){button.dataset.originalLabel=button.textContent;button.disabled=true}if(e.submitter)e.submitter.textContent='保存中…';Object.assign(r,values,{publicOnly:false,imageMatch:f.get('imageMatch'),evidence:safeUrl(f.get('evidence')),watch:f.has('watch'),pageState:f.get('pageState'),needsRecheck:false,reviewedAt:savedReviewAt});const review=recordReview(state.monitor,prior,r,r.reviewedAt),event=appendReview(state.monitor,review);if(event)event.reviewRecord=review;if(event){event.workspaceUrl=location.origin+location.pathname;event.chartPng=eventChart(event);}save();const result=await flush();if(!result?.fullOK){for(const key of Object.keys(r))delete r[key];Object.assign(r,prior);if(review)state.monitor.reviews=state.monitor.reviews.filter(x=>x.id!==review.id);if(event)state.monitor.updateChain=state.monitor.updateChain.filter(x=>x.id!==event.id);throw Error('本机保存失败，本次阶段变更已撤回；请保留窗口重试或导出备份');}scheduleSync();$('#detail').close();if(routeParams.has('lead')){routeParams.delete('lead');history.replaceState(null,'','#inbox?'+routeParams.toString());lastHash='';}render();notify('处理已确认：'+workflowLabel(r)+'；补充信息已保存，云端归档以同步回执为准')}else{const url=safeUrl(f.get('url'));if(!url)throw Error('请输入有效的 HTTP / HTTPS 页面链接');const row=enrichLead({...Object.fromEntries(f),url,checkedAt:new Date().toISOString(),status:'pending',verification:'manual-unverified',source:'人工收录 · 原页面待核查',keywords:split(f.get('query')),queryProvenance:f.get('searchUrl')?'recorded':'reconstructed',imageMatch:'unverified'});queueImageCheck(row);observe(state.monitor,[row],state.rows,{at:row.checkedAt,method:'manual',runId:'manual-'+crypto.randomUUID()});state.rows=mergeRows(state.rows,[row]);save();$('#detail').close();render();detail(state.rows.find(r=>canonical(r.url)===canonical(url)).id);scheduleSync();void retryLeadImages(state.rows.find(r=>canonical(r.url)===canonical(url)).id)}}catch(error){notify(error.message)}finally{if(e.target.id==='review-form'){delete e.target.dataset.saving;for(const button of e.target.querySelectorAll('[type=submit]')){button.disabled=false;button.textContent=button.dataset.originalLabel||button.textContent}}}});
document.addEventListener('toggle',e=>{if(e.target.id==='report-evidence')reportEvidence=e.target.open},true);
window.addEventListener('hashchange',()=>{if($('#detail').open)$('#detail').close();render();window.scrollTo({top:0,behavior:'instant'})});
window.addEventListener('beforeunload',e=>{if(busy){e.preventDefault();e.returnValue=''}});
window.addEventListener('storage',e=>{if((e.key===KEY||e.key==='fjd-watch-task-v3')&&!busy){stale=true;$('#storage-warning').hidden=false;$('#storage-warning').textContent='另一个标签页更新了本机记录。请刷新此页面后再编辑，避免覆盖最新复核。';document.querySelectorAll('button,input,select,textarea').forEach(x=>x.disabled=true);storageOK=false}});
function watchPlan(r){const query='"'+r.url.replaceAll('"','')+'"' ;return {id:'watch:'+canonical(r.url),watchUrl:r.url,query,aliases:state.config.aliases,platform:r.platform||'dealer',country:r.country||'US',language:r.language||'en',searchUrl:'https://www.google.com/search?'+new URLSearchParams({q:query}),domain:new URL(r.url).hostname}}
function watchView(){const rows=state.rows.filter(r=>r.watch);return `<section class="panel"><div class="panel-head"><div><h2>重点网址持续复查 <small>${rows.length} 条</small></h2><p class="helper">持续跟进已发现或人工指定的具体页面，发现变化后重新核查。</p></div><button class="primary" data-action="watch-run" ${busy||!rows.length?'disabled':''}>复查下一批重点网址</button></div><label><input id="include-watch" type="checkbox" ${state.includeWatch?'checked':''}> 每批优先复查最多 2 个重点网址，其余配额用于发现新线索</label><p class="helper space">复查通过公开索引查找原链接。未命中或请求失败会进入日报补查区，不会自动标记下架。普通页面可在线索详情中勾选“重点监控”。</p>${rows.length?`<div class="watch-list">${rows.slice(0,8).map(r=>`<div><button data-detail="${esc(r.id)}">${esc(r.title)}</button><small>${r.needsRecheck?'内容变化待复核':'按批次轮转'} · ${link(r.url,'原页')}</small></div>`).join('')}</div>${rows.length>8?`<button class="space" data-action="watch-inbox">查看全部 ${rows.length} 条重点线索</button>`:''}`:''}<details class="space"><summary>批量加入重点网址</summary><p class="helper">每行一个完整网页 URL，最多 100 条。同一页面自动合并；此操作仅建立监控清单，不算检索发现。</p><textarea id="watch-urls" rows="4" placeholder="https://example.com/product/at2"></textarea><button data-action="watch-add" class="space">加入监控清单</button></details></section>`}
function enhanceDetail(r){
 if(r.needsRecheck)$('#review-form').insertAdjacentHTML('afterbegin','<div class="notice warning">该线索已标记待重新核对，请结合实际证据处理；此标记不自动改变处理阶段。</div>');
 const key=canonical(r.url),events=[...state.monitor.observations.filter(x=>x.key===key).map(x=>({at:x.kind==='changed'?(x.changedAt||x.at):x.lastAt,title:{new:'首次发现',changed:'内容信号变化',repeat:'再次发现'}[x.kind],text:x.snapshot.title})),...state.monitor.reviews.filter(x=>x.key===key).map(x=>({at:x.at,title:'人工处理',text:(x.after.reviewWorkflow?workflowLabel(x.after)+' · '+workflowDetail(x.after):(x.after.decision||statuses[x.after.status]||'更新记录'))+' · '+(x.after.note||'')})),...state.monitor.checks.filter(x=>x.key===key).map(x=>({at:x.at,title:'重点复查',text:{indexed:'公开索引命中原链接','not-found':'索引未命中，不能据此认定下架',error:'查询失败，需补查'}[x.result]}))].sort((a,b)=>b.at.localeCompare(a.at));
 $('#detail').insertAdjacentHTML('beforeend',`<section class="panel space"><div class="panel-head"><h3>事件时间线与证据索引</h3><button data-evidence-id="${esc(r.id)}">导出证据索引 · SHA-256</button></div><p class="helper">导出已收录的标题、摘要、查询词、来源时间及人工处理记录，并提供内容摘要校验值；不包含自动抓取的完整网页、截图或公证时间戳。</p><div class="event-timeline">${events.slice(0,20).map(e=>`<div><a href="#daily?day=${dayOf(e.at)}">${dayOf(e.at)} ${fmt(e.at).slice(-5)} · 日报 ↗</a><b>${e.title}</b><p>${esc(e.text)}</p></div>`).join('')||'<p class="helper">这是升级前的底库记录。后续检索、变化和处理会按实际时间记录，历史不补造。</p>'}</div>${events.length>20?'<p class="helper">显示最近 20 项；完整记录随证据索引导出。</p>':''}</section>`);
}
async function retryLeadImages(id){
 const row=state.rows.find(r=>r.id===id);if(!row||stale)return;
 const button=document.querySelector('[data-image-retry]');if(button?.disabled)return;
 if(button){button.disabled=true;button.textContent='比对中…'}
 try{queueImageCheck(row,{force:true});await enrichBrowserPictures([row],state.selectedBrandIds,{limit:1,force:true,customAssets:state.customAssets,legacy:false});save();const result=await flush();if(!result?.fullOK)throw Error('图片比对尚未完整保存，请重试或导出备份');scheduleSync();
  if($('#detail')?.open&&$('#detail [data-image-retry]')?.dataset.imageRetry===id)$('#image-match-slot').innerHTML=imageMatchEvidence(row,{customAssets:state.customAssets});drawTable();notify('图片证据已保存；'+(cloudCredentials().password&&cloudCredentials().token?'已加入同步队列，云端继续核验局部与变换素材。':'连接云端后可继续核验局部与变换素材。')+'处理阶段保持不变。');
 }catch(e){notify(e.message||'图片比对暂未完成，原有证据保留')}finally{if(button?.isConnected){button.disabled=false;button.textContent='重新比对图片'}}
}
async function handleMonitorClick(b){
 if(b.dataset.imageRetry){await retryLeadImages(b.dataset.imageRetry);return true}

 if(b.dataset.configTab){state.configFolds={...state.configFolds,[b.dataset.configTab==='brands'?'brands':'markets']:true};render();return true}
 if(b.dataset.day){reportDay=b.dataset.day;location.hash='daily?day='+reportDay;return true}
 if(b.dataset.reportMode){reportMode=b.dataset.reportMode;render();return true}
 if(b.dataset.reportDetail){const r=state.rows.find(r=>canonical(r.url)===b.dataset.reportDetail);if(r)detail(r.id);else notify('当前台账中没有此页面，日报中仍保留当时摘要');return true}
 if(b.dataset.evidenceId){const r=state.rows.find(r=>r.id===b.dataset.evidenceId);download('FJD-证据索引-'+dayOf()+'-'+String(r.id||'page').slice(0,16)+'.json',JSON.stringify(await evidencePackage(r,state.monitor),null,2));notify('已导出证据索引与 SHA-256 校验值');return true}
 if(b.dataset.retryQuery){const item=state.monitor.runs.find(r=>r.id===b.dataset.retryQuery)?.items.find(i=>i.at===b.dataset.queryAt);if(item?.plan)await runBatch(item.plan,'retry');return true}
 switch(b.dataset.action){
 case'day-prev':reportDay=shiftDay(reportDay,-1);location.hash='daily?day='+reportDay;return true;
 case'day-next':if(reportDay<dayOf())reportDay=shiftDay(reportDay,1);location.hash='daily?day='+reportDay;return true;
 case'day-today':reportDay=dayOf();location.hash='daily?day='+reportDay;return true;
 case'report-share':reportDialog();return true;
 case'report-html':{const publication=finalizeReport(state.monitor,reportDay);save();download('丰疆监控日报-'+reportDay+'.html',dailyHTML(state.monitor,reportDay,{pname,cname,publication,state}),'text/html;charset=utf-8');$('#detail').close();render();notify('已导出当日累计图表与更新链；Notion 按日期追加归档');return true;}
 case'watch-inbox':filter.follow='watch';location.hash='inbox';return true;
 case'watch-run':{const rows=state.rows.filter(r=>r.watch);if(!rows.length){notify('请先加入重点网址');return true}const queue=Array.from({length:Math.min(state.batchSize,rows.length)},(_,i)=>watchPlan(rows[(state.watchCursor+i)%rows.length]));await runBatch(queue,'watch');return true}
 case'watch-add':{if(busy){notify('请等待本批检索完成再调整清单');return true}const values=$('#watch-urls').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(values.length>100)throw Error('每次最多加入 100 条网址');const valid=[...new Set(values.map(canonical).filter(Boolean))];if(!valid.length)throw Error('请填写有效的 HTTP / HTTPS 网页链接');const rows=valid.filter(url=>!state.rows.some(r=>canonical(r.url)===url)).map(url=>enrichLead({url,title:'待核查页面 · '+new URL(url).hostname+new URL(url).pathname,platform:'dealer',country:state.config.regions[0]||'US',source:'人工指定监控网址 · 尚未检索',verification:'manual-unverified',watch:true,status:'pending',checkedAt:null}));state.rows=mergeRows(state.rows,rows).map(enrichLead);for(const r of state.rows)if(valid.includes(canonical(r.url)))r.watch=true;state.monitor=initMonitor(state.monitor,state.rows);save();render();notify(`已将 ${valid.length} 条网址加入重点清单；${values.filter(x=>!safeUrl(x)).length} 条无效链接未导入`);return true}
 default:return false;
 }
}

function applyBrands(){
 const groups=catalog.entries.filter(g=>state.selectedBrandIds.includes(g.id));
 state.config.aliases=[...new Set([...(state.customAliases||[]),...groups.flatMap(g=>g.searchTerms)])];
 state.config.aliasTerritories=aliasTerritories(catalog,state.selectedBrandIds);state.config.termRules=groups.flatMap(g=>g.termRules);state.config.languageMode='all';
}
function reportDialog(){const events=chainFor(state.monitor,reportDay),receipt=events.map(e=>state.archive?.receipts?.[e.id]).find(r=>r?.publicUrl);$('#detail').innerHTML=`<button class="close" data-action="close" aria-label="关闭">✕</button><div class="eyebrow">DAILY REPORT</div><h2>${reportDay} · 日报归档与导出</h2><p>当天 ${events.length} 次更新分别保留。Notion 每天一页，手动补查与复核继续追加；飞书每天只推送一次摘要与归档链接。</p><div class="report-export-options"><a class="button primary" href="${esc(receipt?.publicUrl||notionPublicUrl)}" target="_blank" rel="noopener"><b>${receipt?'打开当日 Notion 日报':'打开 Notion 日报总页'} ↗</b><small>公开站点 · 阅读无需登录</small></a><button data-action="report-html" ${busy?'disabled':''}><b>下载可视化报告</b><small>HTML 完整快照 · 含内部复核依据</small></button></div><div class="actions"><button data-action="archive-sync">补同步待传记录</button><a href="#data" data-action="close">查看归档与推送状态 →</a></div><p class="helper space">公开归档不含内部备注与授权材料；以 Notion 写入回执确认归档成功。</p>`;$('#detail').showModal();}
async function handleFeatureClick(b){
 const action=b.dataset.action;
 if(action==='scope-global'){if(operationBusy()){notify('请等待当前任务完成');return true}delete state.monitorScopeVersion;upgradeGlobalScope(state);configChanged();render();notify('已启用中国和全部海外市场、平台；请保存任务同步云端');return true}
 if(await handleCloudClick(b))return true;if(await handleDeliveryClick(b))return true; if(['brands-all','brands-clear','save-task','refresh'].includes(action)&&operationBusy()){notify('当前检索正在执行，请等待本批结束');return true;}
 if(action==='brands-all'||action==='brands-clear'){state.selectedBrandIds=action==='brands-all'?catalog.entries.map(g=>g.id):[];applyBrands();configChanged();render();return true;}
 if(action==='save-task'){state.taskName=$('#task-name').value;state.taskSavedAt=new Date().toISOString();state.schedule=normalizeSchedule({enabled:$('#schedule-enabled').checked,cadence:$('#cadence').value,hour:+$('#hour').value,weekday:state.schedule.weekday,every:state.schedule.every,timezone:'Asia/Shanghai'});state.nextDue=nextScheduleAt(state.schedule);save();const result=await flush();if(state.cloudMode&&cloudCredentials().password&&cloudCredentials().token)await saveCloudTask(state);else if(state.cloudMode){notify('任务已保存本机；连接同步权限后可应用到云端定时任务');return true}notify(result.taskOK?'任务已保存，下次打开会恢复':'保存失败，请导出完整备份');return true;}
 if(action==='refresh'){state.cursor=0;state.completed=[];state.cycle=(state.cycle||1)+1;reportDay=dayOf();reportMode='delta';await runBatch(null,'refresh');return true;}
 return false;
}

function importPublicScan(){
 if((state.importedPublicScans||[]).includes(publicScan.id))return false;
 const h={id:publicScan.id,startedAt:publicScan.at,endedAt:publicScan.items.at(-1).at,trigger:'public-collector',planned:publicScan.items.length,attempted:publicScan.items.length,success:0,failed:0,added:0,items:[],delta:[],running:false,assetNames:[],scope:publicScan.scope};
 for(const item of publicScan.items){const rows=publicScan.rows.filter(r=>r.platform===item.platform);const before=state.rows.length;const changes=observe(state.monitor,rows,state.rows,{at:item.at,runId:h.id,query:item.plan.query,searchUrl:item.searchUrl});for(const c of changes)h.delta.push({key:c.key,kind:c.isNew?'new':c.changed?'changed':'repeat'});state.rows=mergeRows(state.rows,rows).map(enrichLead);const added=state.rows.length-before;h.added+=added;h[item.status==='成功'?'success':'failed']++;h.items.push({...item,added});}
 state.history.unshift(h);recordRun(state.monitor,h);state.importedPublicScans=[...(state.importedPublicScans||[]),publicScan.id];return true;
}
async function init(){try{const initialSnapshot=readLocalSnapshot();const [raw,language,manifest,brands,scan]=await Promise.all(['leads.json','platform-languages.json','assets/manifest.json','brand-catalog.json','public-scan.json'].map(async p=>{const r=await fetch('./'+p+'?v=20261020-review',{signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('数据加载失败 '+r.status);return r.json()}));seeds=raw;registry=language;catalog=brands;publicScan=scan;assets=[...manifest.assets,...catalog.assets.map(a=>({id:'excel-'+a.file,excelFile:a.file,filename:'excel/'+a.file,name:catalog.entries.find(g=>g.assetFiles.includes(a.file))?.canonicalName||a.file,kind:'symbol'}))];let saved=await loadState();
 state={...saved,config:normalizeConfig(saved.config),rows:mergeRows((saved.rows||saved.leads||[]).filter(r=>safeUrl(r.url)).map(enrichLead),seeds.filter(r=>!(saved.rows||saved.leads||[]).some(old=>canonical(old.url)===canonical(r.url)))).map(enrichLead),schedule:normalizeSchedule(saved.schedule||{enabled:true,hour:9,timezone:'Asia/Shanghai'}),batchSize:[20,60,120,300].includes(saved.batchSize)?saved.batchSize:60,assetIds:saved.assetIds||['fjdynamics-shield','fjdynamics-wordmark'],customAssets:saved.customAssets||[],history:saved.history||[],cursor:saved.cursor||0,completed:saved.completed||[],cycle:saved.cycle||1,lastSuccess:saved.lastSuccess||null,lastAttempt:saved.lastAttempt||null,includeWatch:saved.includeWatch!==false,watchCursor:saved.watchCursor||0};state.selectedBrandIds=Array.isArray(saved.selectedBrandIds)?saved.selectedBrandIds:catalog.entries.map(g=>g.id);state.customAliases=saved.customAliases||saved.config?.aliases||defaults.aliases;state.catalogVersion=1;if(!saved.chinaScopeVersion){state.config.regions=[...new Set(['CN',...state.config.regions])];state.config.platforms=[...new Set([...chinaPlatforms.map(p=>p.id),...state.config.platforms])];state.cursor=0;state.completed=[];}state.chinaScopeVersion=1;upgradeGlobalScope(state);state.taskName=saved.taskName||'中国与海外品牌日常监控';state.deviceId=saved.deviceId||crypto.randomUUID();applyBrands();state.monitor=initMonitor(saved.monitor,state.rows);if(!saved.monitor)state.monitor.legacyRuns=structuredClone(state.history);state.history.forEach(h=>{if(h.running){h.running=false;h.cancelled=true;recordRun(state.monitor,h)}});assets.push(...state.customAssets);state.nextDue=saved.nextDue||nextScheduleAt(state.schedule);const imported=importPublicScan();migrateChain(state.monitor);state.archive||={receipts:{}};state.archive.receipts||={};state.siteCursors||={};state.cloudMode=true;state.publicFeedLoading=true;rebuild();if(saved.queueVersion!==2){state.cursor=0;state.completed=[];state.queueVersion=2;save()}state.cursor=plans.length?state.cursor%plans.length:0;const snapshot=await initialSnapshot;if(snapshot){applyPublicFeed(state,snapshot.feed);if((Date.parse(snapshot.status.updatedAt)||0)>=(Date.parse(state.cloudStatusAt)||0)){state.automation=snapshot.status.automation||state.automation;if(!state.cloudService?.queuedAt||Date.parse(snapshot.status.runtime.startedAt)>=Date.parse(state.cloudService.queuedAt))state.cloudService=snapshot.status.runtime;state.cloudStatusAt=snapshot.status.updatedAt;}state.publicFeedLoading=false;}storageStatus=saved.savedAt?'已恢复上次保存 · '+fmt(saved.savedAt):'新任务，尚无执行记录';if(imported||!saved.catalogVersion||!saved.chinaScopeVersion)save();save();render();scheduleSync();setInterval(scheduleSync,30000);
 }catch(e){$('#app').innerHTML=`<div class="panel"><h1>页面数据未能加载</h1><p>${esc(e.message)}</p><p>请刷新重试，或打开 <a href="./connectivity/">访问诊断页</a>。</p></div>`}}
init();

function operationBusy(){return busy;}
function dataSyncView(){
 const pending=pendingLocalEvents(state).length,c=cloudCredentials();
 const message=state.publicFeedLoading?'正在读取各设备共用的云端日报…':state.publicUpdatedAt?'云端公开数据已读取 · '+fmt(state.publicUpdatedAt):'云端公开数据尚未读取；当前显示本机已有记录';
 return `<div class="notice ${state.cloudStatusError?'warning':''}" id="data-sync-status" role="status">${esc(message)}${state.cloudStatusError?'<br>'+esc(state.cloudStatusError)+' <button class="site-action" data-action="cloud-read">重新读取日报</button> <a href="'+notionPublicUrl+'" target="_blank" rel="noopener">查看 Notion 归档 ↗</a>':''}${pending?`<br>本机待同步 ${pending} 次更新 · ${c.password&&c.token?'已连接同步权限，等待云端接收及 Notion 回执':'需连接本浏览器的同步权限，其他设备暂不可见'} <a href="./cloud/portal.html#browser-connection">连接同步权限</a>`:''}${state.priorityPendingIds?.length?`<br>本机待同步 ${state.priorityPendingIds.length} 次优先级调整 · ${c.password&&c.token?'等待云端接收':'需连接本浏览器同步权限'} <a href="./cloud/portal.html#browser-connection">连接同步权限</a>`:''}<small style="display:block">手动检索在网页执行；云端公开日报自动跨设备读取，内部备注需解锁加密台账。</small></div>`;
}
function redrawSyncedData(){if(route==='tasks'){const status=$('#data-sync-status');if(status)status.outerHTML=dataSyncView();drawRun();}else render();}
function scheduleSync(force=false){if(!state||busy||syncBusy||stale)return;if(!cloudCredentials().password){syncBusy=true;refreshRuntime(state).then(()=>{save();redrawSyncedData()}).catch(e=>{state.publicFeedLoading=false;state.cloudStatusError=e.message;redrawSyncedData()}).finally(()=>syncBusy=false);return;}cloudRefreshAndSync(force).catch(async e=>{state.archive.lastError=e.message;try{await refreshRuntime(state)}catch{}state.publicFeedLoading=false;save();redrawSyncedData()});}
async function handleDeliveryClick(b){
 if(b.dataset.ownerSave){const card=b.closest('.brand-group'),id=b.dataset.ownerSave;state.config.brandOwnership||={};state.config.brandOwnership[id]={company:card.querySelector('[data-owner-company]').value.trim().slice(0,120),scope:card.querySelector('[data-owner-category]').value,updatedAt:new Date().toISOString()};state.cloudTaskDirty=true;state.taskSavedAt=new Date().toISOString();save();const c=cloudCredentials();if(c.password&&c.token){await saveCloudTask(state);save();notify('公司归属已保存并提交云端同步')}else notify('公司归属已保存在本机；连接同步权限后可保存任务至云端');return true;}
 if(b.dataset.siteGroup){state.siteGroup=b.dataset.siteGroup;save();render();return true;}
 if(b.dataset.siteGroupRetry){if(operationBusy()){notify('请等待当前任务结束或暂停后补查');return true}const queue=groupedSiteQueue(plans,state.completed,operationSites(state,plans),{group:b.dataset.siteGroupRetry,cursors:state.siteCursors,failed:dayReport(state.monitor,dayOf()).pendingFailures.map(i=>i.plan)});if(!queue.length){notify('该分类没有可执行的站点');return true}state.browserRetryQueue={group:b.dataset.siteGroupRetry,plans:queue,startedAt:new Date().toISOString()};save();await runBatch(queue,'site-retry');return true;}
 if(b.dataset.action==='resume-site-retry'){const current=new Map(plans.map(p=>[p.id,p]));if(state.browserRetryQueue)state.browserRetryQueue.plans=(state.browserRetryQueue.plans||[]).filter(p=>current.has(p.id));const queue=state.browserRetryQueue?.plans||[];if(queue.length)await runBatch(queue,'site-retry');else notify('剩余查询已不在当前配置范围，请重新选择补查分类');return true;}

 if(b.dataset.sitePlatform){if(operationBusy()){notify('当前任务执行中，请完成或暂停后再补查');return true}const site={platform:b.dataset.sitePlatform,domain:b.dataset.siteDomain||''},key=site.platform+'|'+site.domain,scoped=plans.filter(p=>p.platform===site.platform&&(p.domain||'')===site.domain);const queue=sitePlans(plans,state.completed,site,{limit:Math.min(5,state.batchSize),cursor:state.siteCursors[key]||0,failed:dayReport(state.monitor,dayOf()).pendingFailures.map(i=>i.plan)}).map(p=>({...p,siteRetryKey:key,sitePosition:scoped.findIndex(x=>x.id===p.id)}));if(!queue.length){notify('该站不在当前有效查询范围，请先在监控配置启用市场与品牌');return true}await runBatch(queue,'site-retry');return true}
 if(b.dataset.action==='archive-sync'){
  if($('#detail').open)$('#detail').close();
  const c=cloudCredentials();if(!c.password||!c.token){location.href='./cloud/portal.html#sync';return true}
  if(syncBusy){notify('正在检查归档状态，请稍候');return true}
  await cloudRefreshAndSync(true);notify('已检查待传记录；仅 Notion 确认写入后显示已归档');return true;
 }
 return false;
}

async function handleCloudClick(b){if(b.dataset.action==='cloud-read'){refreshCloudSnapshot();if(!cloudCredentials().password){await refreshRuntime(state);save();render();notify(state.cloudStatusError||'已读取云端公开日报与线索；内部核查依据需解锁加密台账。');return true}await refreshCloud(state);save();render();notify('已读取云端最新台账，当前浏览器已切换云端执行');return true}if(b.dataset.action==='cloud-local'){state.cloudMode=false;save();render();notify('当前浏览器已切回页面内执行；云端计划仍保留，可在 GitHub 暂停工作流');return true}return false;}
async function cloudRefreshAndSync(force=false){if(syncBusy||!cloudCredentials().password)return;syncBusy=true;try{await syncArchive(state,{force});state.publicFeedLoading=false;save();redrawSyncedData()}finally{syncBusy=false}}


document.addEventListener('submit',async e=>{
 if(e.target.id!=='priority-form')return;e.preventDefault();if(e.target.dataset.saving)return;
 if(stale){notify('请刷新以读取最新记录');return}
 const row=state.rows.find(r=>r.id===e.target.dataset.id);if(!row){notify('线索已更新，请重新打开');return}
 const prior=structuredClone(row.priorityV2),priorPending=[...(state.priorityPendingIds||[])],button=e.target.querySelector('[type=submit]');
 try{
  const f=new FormData(e.target);e.target.dataset.saving='true';button.disabled=true;
  const event=adjustPriority(row,f.get('priorityLevel'),f.get('priorityReason'));
  state.priorityPendingIds=[...new Set([...priorPending,event.id])];save();const result=await flush();
  if(!result?.fullOK){row.priorityV2=prior;state.priorityPendingIds=priorPending;throw Error('优先级未能保存，本次调整已撤回，请重试或导出备份')}
  $('#priority-slot').innerHTML=priorityDetail(row,{fmt});if(route==='inbox')drawTable();
  const c=cloudCredentials();notify('优先级已保存：'+priorityLabels[priorityOf(row).level]+'；线索处理阶段保持不变。'+(c.password&&c.token?'已进入云端同步队列。':'当前保存在本机，连接同步权限后可跨设备同步。'));scheduleSync();
 }catch(error){notify(error.message)}finally{delete e.target.dataset.saving;button.disabled=false}
});
